// Transform Apify output to YouTube API-like structure
const items = $input.all();
const results = [];

for (const item of items) {
  const video = item.json;

  // Map Apify fields to snippet/statistics
  const transformed = {
    json: {
      id: video.id,
      videoId: video.id,
      snippet: {
        title: video.title,
        description: video.description || '',
        publishedAt: video.datePublished || video.uploadDate || new Date().toISOString(),
        channelTitle: video.channelName,
        thumbnails: {
          default: { url: video.thumbnailUrl }
        }
      },
      statistics: {
        viewCount: String(video.viewCount || 0),
        likeCount: String(video.likes || 0),
        commentCount: String(video.comments || 0)
      },
      subscriberCount: video.numberOfSubscribers || 5000,
      channelUrl: video.channelUrl,
      duration: video.duration
    }
  };
  results.push(transformed);
}

return results;

// Calculate outlier score (High Views / Low Subscribers = Viral Topic)

const items = $input.all();

if (!items || items.length === 0) {
  return [];
}

const seen = new Set();
const filtered = [];

for (const item of items) {
  const videoId = item.json.id?.videoId || item.json.id || item.json.videoId;

  if (!videoId || seen.has(videoId)) continue;

  seen.add(videoId);

  const snippet = item.json.snippet || {};
  const stats = item.json.statistics || {};

  const views = Number(stats.viewCount) || 0;
  const likes = Number(stats.likeCount) || 0;
  const comments = Number(stats.commentCount) || 0;

  const subscribers = Number(item.json.subscriberCount) || 5000;

  if (views === 0) continue;

  const outlierScore = views / (subscribers + 100);
  const engagementRate = views > 0 ? (comments / views) : 0;

  const publishedAt = new Date(snippet.publishedAt || Date.now());
  const ageHours = (Date.now() - publishedAt.getTime()) / (1000 * 60 * 60);

  if (ageHours <= 72 && views >= 500 && views <= 100000) {
    if (outlierScore >= 0.3 || engagementRate >= 0.05) {
      filtered.push({
        json: {
          ...item.json,
          videoId: videoId,
          title: snippet.title,
          channelTitle: snippet.channelTitle,
          views: views,
          likes: likes,
          comments: comments,
          subscribers: subscribers,
          ageHours: Number(ageHours.toFixed(2)),
          outlierScore: Number(outlierScore.toFixed(4)),
          engagementRate: Number(engagementRate.toFixed(4))
        }
      });
    }
  }
}

filtered.sort((a, b) => b.json.outlierScore - a.json.outlierScore);

return filtered;

// Calculate viral velocity metrics
const items = $input.all();
const results = [];

for (const item of items) {
  const json = item.json;

  const views = parseInt(json.statistics?.viewCount || 0);
  const publishedAt = new Date(json.snippet?.publishedAt || Date.now());
  const hoursSincePublish = (Date.now() - publishedAt.getTime()) / (1000 * 60 * 60);

  const velocity = hoursSincePublish > 0 ? views / hoursSincePublish : 0;
  const acceleration = velocity / Math.max(hoursSincePublish, 1);

  const text = (json.snippet?.title || '') + ' ' + (json.snippet?.description || '');
  const keywords = text.toLowerCase()
    .split(/\W+/)
    .filter(w => w.length > 4 && !["video", "watch", "subscribe", "channel"].includes(w))
    .slice(0, 10);

  const normalizedOutlier = Math.min(json.outlierScore || 0, 10) / 10;

  results.push({
    json: {
      ...json,
      viralMetrics: {
        velocity,
        acceleration,
        normalizedOutlier,
        engagementRate: json.engagementRate || 0,
        keywords,
        hoursSincePublish
      }
    }
  });
}

return results;

// Apply velocity-based scoring
const items = $input.all();
const results = [];

const weights = {
  velocity: 0.40,
  acceleration: 0.30,
  outlier: 0.20,
  engagement: 0.10
};

for (const item of items) {
  const metrics = item.json.viralMetrics || {};
  const views = parseInt(item.json.statistics?.viewCount || 0);

  const velocityScore = Math.min(100, (metrics.velocity || 0) / 10);
  const accelerationScore = Math.min(100, (metrics.acceleration || 0) * 5);
  const outlierScore = (metrics.normalizedOutlier || 0) * 100;
  const engagementScore = Math.min(100, (metrics.engagementRate || 0) * 2000);

  const earlyBonus = (metrics.hoursSincePublish <= 48 && views <= 50000) ? 20 : 0;

  const earlyMomentumScore = 
    (velocityScore * weights.velocity) +
    (accelerationScore * weights.acceleration) +
    (outlierScore * weights.outlier) +
    (engagementScore * weights.engagement) +
    earlyBonus;

  results.push({
    json: {
      ...item.json,
      scores: {
        velocityScore,
        accelerationScore,
        outlierScore,
        engagementScore,
        earlyMomentumScore
      }
    }
  });
}

results.sort((a, b) => b.json.scores.earlyMomentumScore - a.json.scores.earlyMomentumScore);

return results;

