// Group videos by niche and limit to 4 per niche
const items = $input.all();
const niches = {
  "Technology": [],
  "Coding": [],
  "Software Engineering": [],
  "System Design": [],
  "Aviation": [],
  "Cars": []
};

for (const item of items) {
  const text = (item.json.snippet?.title || '') + ' ' + (item.json.snippet?.description || '');
  const lower = text.toLowerCase();

  if (lower.includes('aviation') || lower.includes('aircraft') || lower.includes('flight')) {
    if (niches["Aviation"].length < 4) niches["Aviation"].push(item);
  } else if (lower.includes('car') || lower.includes('automotive') || lower.includes('vehicle')) {
    if (niches["Cars"].length < 4) niches["Cars"].push(item);
  } else if (lower.includes('system design') || lower.includes('architecture')) {
    if (niches["System Design"].length < 4) niches["System Design"].push(item);
  } else if (lower.includes('software engineering') || lower.includes('developer')) {
    if (niches["Software Engineering"].length < 4) niches["Software Engineering"].push(item);
  } else if (lower.includes('coding') || lower.includes('programming')) {
    if (niches["Coding"].length < 4) niches["Coding"].push(item);
  } else if (lower.includes('tech') || lower.includes('technology')) {
    if (niches["Technology"].length < 4) niches["Technology"].push(item);
  }
}

const results = [];
for (const [niche, videos] of Object.entries(niches)) {
  for (const video of videos) {
    results.push({
      json: {
        ...video.json,
        assignedNiche: niche
      }
    });
  }
}

return results;

